SELECT s.*, e.code AS equipment_code, e.name AS equipment_name, m.order_no AS maintenance_no, u.nickname AS create_by_name
FROM mes_equipment_stop s
JOIN mes_equipment e ON e.id = s.equipment_id
LEFT JOIN mes_maintenance m ON m.id = s.maintenance_id
LEFT JOIN sys_user u ON u.id = s.create_by

    s.equipment_id = #{equipmentId}
    AND s.end_time > #{from}
    AND s.start_time < #{to}
    AND s.reason = #{reason}

ORDER BY s.start_time DESC, s.id DESC

SELECT * FROM mes_equipment_stop
WHERE end_time > #{from} AND start_time < #{to}
AND equipment_id = #{equipmentId}
